from ute_core.exception import CoreException


class KeywordControlException(CoreException):
    """Base exception for ute_common_interface library."""


class KeywordNotExecutedException(KeywordControlException):
    """Exception raised when demanded keyword wasn't run before"""


class DecorationNotSupportedException(KeywordControlException):
    """Exception raised when decorator is used to decorate function not method."""
